/// <summary>
/// designed by AVANADE from AX2009 KCS_SalesQuotationQuickCopying 
/// </summary>
class AVASalesQuotationQuickCopying extends RunBaseBatch
{
    SalesQuotationTable     toSalesQuotationTable;
    SalesQuotationTable     fromSalesQuotationTable;                            

    AVASpecialDiscQuotation fromDisc;     
    KCS_HDMSalesQuotationTableInfoFields    fromSalesQuotationTableInfoFields;

    // Packed variables
    QuotationId             fromQuotationId;
    boolean                 copyCrossCompany;                                   
    DataAreaId              fromDataArea;                                      
    RecordInsertList        recordInsertList;                                   
    int                     y;                                                  
    KCS_KBVSalesTenderLink  salesTenderLink;                                    
    KCS_KBVBuildingProjectID    buildingProjectId;                              
    QuotationId             toQuotationId;   
    DataAreaId              toDataArea; 

    // Dialog fields
    DialogField             dlgFromQuotationId;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        fromQuotationId,
        fromDataArea,                                                            
        buildingProjectId,                                                      
        toQuotationId                                                           
    #endmacro


}

