/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "args">args</param>
static void main(Args args)
{
    AVASalesQuotationQuickCopying    salesQuotationQuickCopying;
    salesQuotationQuickCopying = AVASalesQuotationQuickCopying::construct(args.parmEnum());

    if(args && args.parmEnumType())
    {
        salesQuotationQuickCopying.parmCopyCrossCompany(args.parmEnum());
    }

    if(args && args.dataset() == tableNum(SalesQuotationTable))
    {
        salesQuotationQuickCopying.parmFromDataArea(curext());
        salesQuotationQuickCopying.parmBuildingProjectId(args.record().(fieldNum(SalesQuotationTable, KCS_KBVBuildingProjectID)));
        salesQuotationQuickCopying.parmToQuotationId(args.record().(fieldNum(SalesQuotationTable, QuotationID)));
        salesQuotationQuickCopying.saveLast();
    }

    if (salesQuotationQuickCopying.prompt())
    {
        if(args && args.dataset() == tableNum(SalesQuotationTable))
        {
            salesQuotationQuickCopying.parmToSalesQuotationTable(args.record());
        }

        salesQuotationQuickCopying.runOperationNow();
        if(args && args.dataset() == tableNum(SalesQuotationTable))
        {
            SalesQuotationTable         sourceSalesQuotationTable;
            sourceSalesQuotationTable.data(args.record());
            FormDataSource              quotTableDS = args.record().dataSource();
            FormRun                     formRun = quotTableDS.formRun();
            FormDataSource infoFields_DS = formRun.dataSource('KCS_HDMSalesQuotationTableInfoFields');

            quotTableDS.executeQuery();
            quotTableDS.positionToRecord(sourceSalesQuotationTable);

            if (infoFields_DS)
            {
                infoFields_DS.reread();
                infoFields_DS.refresh();
            }

        }

    }
}

