public container pack()
{
    return [#CurrentVersion,#CurrentList];
}

public boolean unpack(container packedClass)
{
    Version version = RunBase::getVersion(packedClass);

    switch (version)
    {
        case #CurrentVersion:
            [version,#CurrentList] = packedClass;
            break;
        default:
            return false;
    }
    return true;
}

public ClassDescription caption()
{    
    return "@NDX:NXACopyCompletely";
}

protected boolean canRunInNewSession()
{
    return true;
}

protected boolean canGoBatchJournal()
{
    return false;
}

/// <summary>
/// AVA WEN
/// </summary>
/// <returns>always returns false</returns>
public boolean canGoBatch()
{
    return false;
    //return true;
}

public boolean runsImpersonated()
{
    return true;
}

protected void runOperationNow()
{
    #OCCRetryCount
    if (! this.validate())
    {
        throw error("@SYS93835");
    }

    try
    {
        ttsbegin;

        this.initDefault();  

        this.copyMatrix();

        this.copy();

        ttscommit;

        //this.Refresh();
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch (Exception::Error)
    {
        Error("@NDX:NXACopyAborted");
        return;
    }
}

public SalesQuotationTable parmFromSalesQuotationTable(SalesQuotationTable _fromSalesQuotationTable = fromSalesQuotationTable)
