/// <summary>
/// designed by AVANADE
/// </summary>
void initDefault()
{
    this.parmFromSalesQuotationTable(SalesQuotationTable::find(fromQuotationId));
    fromDisc = AVASpecialDiscQuotation::find(fromQuotationId, true);
    select firstonly fromSalesQuotationTableInfoFields where fromSalesQuotationTableInfoFields.QuotationId == fromQuotationId;
}

public boolean validate(Object calledFrom = null)
{
    if (!fromQuotationId)
    {
        return CheckFailed("@NDX:NXANoQuotSelected");
    }

    return true;
}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <returns>boolean</returns>
boolean copy()
{
    SalesQuotationLine  salesQuotationLine, fromLine, toLine;
    LineNum             lineNum;
    container           cDataArea;          
    Map                 mDocuCopy           = new Map(Types::Real, Types::Record);                  
    MapEnumerator       mDocuCopyEnum;                                                              

    conins(cDataArea, 1, fromDataArea);
    info(strfmt('%1 %2 ', "@SYS58641", time2str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone()),0,0)));
    recordInsertList = new RecordInsertList(tableNum(SalesQuotationLine), false, true);

    toDataArea = curExt();

    this.copyHeader();

    if (this.parmCopyCrossCompany())
    {
        while select crosscompany:cDataArea salesQuotationLine order by lineNum
                where salesQuotationLine.QuotationId == fromQuotationId
        {
            if (salesQuotationLine.inventTable())
            {
                y++;
                this.copyLine(salesQuotationLine);
                if (DocuRef::exist(this.parmFromDataArea(), tablenum(SalesQuotationLine), salesQuotationLine.RecId))
                {
                    mDocuCopy.insert(y, salesQuotationLine);
                }
            }
            else
            {
                throw Error(strFmt("@NDX:NXAItemDoesntExist", salesQuotationLine.ItemId, curExt()));
            }
        }
    }
    else
    {
        while select salesQuotationLine order by lineNum
                where salesQuotationLine.QuotationId == fromQuotationId
        {
            y++;
            this.copyLine(salesQuotationLine);
            if (DocuRef::exist(this.parmFromDataArea(), tablenum(SalesQuotationLine), salesQuotationLine.RecId))
            {
                mDocuCopy.insert(y, salesQuotationLine);
            }
        }
    }

    recordInsertList.insertDatabase();

    if (!mDocuCopy.empty())
    {
        mDocuCopyEnum = mDocuCopy.getEnumerator();
        while (mDocuCopyEnum.moveNext())
        {
            fromLine = mDocuCopyEnum.currentValue();
            //lineNum = fromLine.buildLineNumFromLVPos();
            lineNum = fromLine.LineNum;
            toLine  = salesQuotationLine::find(toSalesQuotationTable.QuotationId, LineNum);
            Docu::copy(fromLine, toLine);
            //salesQuotationLine = SalesQuotationLine::find(toSalesQuotationTable.QuotationId, mDocuCopyEnum.currentKey());
            //Docu::copy(mDocuCopyEnum.currentValue(), salesQuotationLine);
        }
    }

    info(strfmt("@NDX:NXANumOfCopiedPos", y));
    info(strfmt('%1 %2', "@SYS39128", time2str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone()),0,0)));
    return true;
}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "_salesQuotationLine">SalesQuotationLine</param>
void copyLine(SalesQuotationLine _salesQuotationLine)
{
    SalesQuotationLine   newSalesQuotationLine;
    InventDim            newInventDim, fromInventDim;
    container            cDataArea;

    conins(cDataArea, 1, fromDataArea);

    //buf2Buf(_salesQuotationLine, newSalesQuotationLine);

    newSalesQuotationLine.QuotationId = toSalesQuotationTable.QuotationId;

    newSalesQuotationLine.initFromSalesQuotationTable(toSalesQuotationTable);

    newSalesQuotationLine.KCS_QLLVPosition          = _salesQuotationLine.KCS_QLLVPosition;
    newSalesQuotationLine.KCS_QLInternalPosition    = _salesQuotationLine.KCS_QLInternalPosition;

    newSalesQuotationLine.initFromSalesQuotationLine(_salesQuotationLine);
    newSalesQuotationLine.KCS_MultipleItem = _salesQuotationLine.KCS_MultipleItem;
    newSalesQuotationLine.initFromCustExternalItemDescription();               

    //newSalesQuotationLine.KCS_QLLVPosition          = _salesQuotationLine.KCS_QLLVPosition;
    //newSalesQuotationLine.KCS_QLInternalPosition    = _salesQuotationLine.KCS_QLInternalPosition;

    newSalesQuotationLine.InventTransId = '';
    //newSalesQuotationLine.LineNum = y;
    //newSalesQuotationLine.LineNum                   = newSalesQuotationLine.buildLineNumFromLVPos();
    newSalesQuotationLine.LineNum = _salesQuotationLine.LineNum;

    //newSalesQuotationLine.KCS_HK2 = newSalesQuotationLine.AVAgetHK2SalesUnit();                                       
    newSalesQuotationLine.avaUpdateHK2();
    newSalesQuotationLine.setPriceDisc(newSalesQuotationLine.inventDim());
    if (_salesQuotationLine.KCS_NotCalculated)
    {
        newSalesQuotationLine.PriceUnit = _salesQuotationLine.PriceUnit;
    }
    fromInventDim = _salesQuotationLine.inventDim();
    //newSalesQuotationLine.KCS_OrgQuotationId = fromQuotationId;
    if (this.parmCopyCrossCompany())
    {
        select crosscompany:cDataArea fromInventDim
            where fromInventDim.inventDimId == _salesQuotationLine.InventDimId;

        newInventDim.clear();
        newInventDim.InventLocationId = fromInventDim.InventLocationId;
        newInventDim.InventSiteId     = fromInventDim.InventSiteId;
        newInventDim.InventStatusId   = fromInventDim.InventStatusId;

        //str dt = curExt(); 

        if(fromInventDim.configId != ''
        || fromInventDim.InventSizeId != ''
        || fromInventDim.InventColorId != ''
        || fromInventDim.InventStyleId != '')
        {
            this.createProductVariant(_salesQuotationLine.ItemId, fromInventDim);

            newInventDim.configId         = fromInventDim.configId;
            newInventDim.InventSizeId     = fromInventDim.InventSizeId;
            newInventDim.InventColorId    = fromInventDim.InventColorId;
            newInventDim.InventStyleId    = fromInventDim.InventStyleId;
        }

        newInventDim = InventDim::findOrCreate(newInventDim);

        newSalesQuotationLine.InventDimId = newInventDim.inventDimId;
    }

    recordInsertList.add(newSalesQuotationLine);
}

/// <summary>
/// designed by AVANADE
/// </summary>
void copyHeader()
{
   // KCS_HDMSalesQuotationTableInfoFields::copyQuotInfoField(salesQuotationTable::find(fromQuotationId), toSalesQuotationTable);
    KCS_HDMSalesQuotationTableInfoFields    toSalesQuotationTableInfoFields;

    toSalesQuotationTable.selectForUpdate(true);
    toSalesQuotationTable.KCS_OrgQuotationId = fromQuotationId;
    toSalesQuotationTable.KCS_RefQuotationId = fromSalesQuotationTable.KCS_RefQuotationId;
    toSalesQuotationTable.KCS_QLStdStepSize  = fromSalesQuotationTable.KCS_QLStdStepSize;
    toSalesQuotationTable.AVANoExpiryOverrun = fromSalesQuotationTable.AVANoExpiryOverrun;
    toSalesQuotationTable.KCS_QuotationShorttext = fromSalesQuotationTable.KCS_QuotationShorttext;
    toSalesQuotationTable.KCS_ShowIntPosPrice   = fromSalesQuotationTable.KCS_ShowIntPosPrice;
    //toSalesQuotationTable.KCS_StatusId  = fromSalesQuotationTable.KCS_StatusId;
    toSalesQuotationTable.KCS_DataArea  = fromSalesQuotationTable.KCS_DataArea;

    if(fromSalesQuotationTableInfoFields)
    {

        ttsbegin;
        toSalesQuotationTableInfoFields             = KCS_HDMSalesQuotationTableInfoFields::find(toSalesQuotationTable.QuotationId, true);
        toSalesQuotationTableInfoFields.InfoField4  = fromSalesQuotationTableInfoFields.InfoField4;
        toSalesQuotationTableInfoFields.InfoField3  = fromSalesQuotationTableInfoFields.InfoField3;
        toSalesQuotationTableInfoFields.QuotationId = toSalesQuotationTable.QuotationId;

        if (toSalesQuotationTableInfoFields.RecId)
        {
            toSalesQuotationTableInfoFields.update();
        }
        else
        {
            toSalesQuotationTableInfoFields.insert();
        }

        ttscommit;
    }      

    this.setSalesTableManualDisc();
    toSalesQuotationTable.doUpdate();

    this.copyHeaderDocu();
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "toDiscId">toDiscId</param>
void setSalesTableManualDisc(QuotationId toDiscId = toSalesQuotationTable.QuotationId)
{
    AVASpecialDiscQuotation     toDisc;

    ttsbegin;
    toDisc = AVASpecialDiscQuotation::find(toDiscId, true);

    toDisc.SpecialDiscountId1           = fromDisc.SpecialDiscountId1;
    toDisc.SpecialDiscountId2           = fromDisc.SpecialDiscountId2;
    toDisc.SpecialDiscountId3           = fromDisc.SpecialDiscountId3;
    toDisc.SpecialDiscountPct1          = fromDisc.SpecialDiscountPct1;
    toDisc.SpecialDiscountPct2          = fromDisc.SpecialDiscountPct2;
    toDisc.SpecialDiscountPct3          = fromDisc.SpecialDiscountPct3;

    toDisc.update();
    ttscommit;
}

/// <summary>
/// designed by AVANADE
/// </summary>
void copyHeaderDocu()
{
    Docu::copyWithoutGAEB(fromSalesQuotationTable, toSalesQuotationTable);
}

/// <summary>
/// designed by AVANADE
/// </summary>
void copyMatrix()
{
    SalesQuotationLine  salesQuotationLine;

    ttsbegin;

    salesTenderLink = KCS_KBVSalesTenderLink::find(toSalesQuotationTable.QuotationId,true);         

    if (salesTenderLink)
    {
        salesTenderLink.delete();
    }
    ttscommit;

    //letzte Position ermitteln
    select firstonly salesQuotationLine order by KCS_QLLVPosition desc
        //where salesQuotationLine.QuotationId == toSalesQuotationTable.QuotationId;
        where salesQuotationLine.QuotationId == fromSalesQuotationTable.QuotationId;

    //LV-Matrix setzen
    ttsbegin;
    salesTenderLink.TenderMatrix = KCS_KBVTenderIdUtility::CreateNewTenderMatrix(salesQuotationLine.KCS_QLLVPosition,salesTenderLink.TenderMatrix);
    //salesTenderLink.QuotationId = SalesQuotationLine.QuotationId;
    salesTenderLink.QuotationId = toSalesQuotationTable.QuotationId;
    salesTenderLink.insert();
    ttscommit;

}

