/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_itemId">_itemId</param>
/// <param name = "_inventDim">_inventDim</param>
/// <returns>existsVariant</returns>
public boolean existsVariant(ItemId _itemId, InventDim _inventDim)
{
    InventDim inventDimLoc;

    inventDimLoc.configId         = _inventDim.configId;
    inventDimLoc.InventSizeId     = _inventDim.InventSizeId;
    inventDimLoc.InventColorId    = _inventDim.InventColorId;
    inventDimLoc.InventStyleId    = _inventDim.InventStyleId;
    inventDimLoc                  = InventDim::findOrCreate(inventDimLoc);

    container dimValueContainer = EcoResProductVariantDimValue::getDimensionValuesContainerByInventDim(inventDimLoc);

    return EcoResProductVariantManager::existDistinctProductVariant(InventTable::find(_itemId).Product().RecId, dimValueContainer);
}

/// <summary>
/// designed from  AVA
/// </summary>
/// <param name = "_itemId">_itemId</param>
/// <param name = "_inventDim">_inventDim</param>
public void createProductVariant(ItemId     _itemId,
                                 InventDim  _inventDim)
{
    InventDim                           inventDimLoc;
    //EcoResConfiguration                 ecoResConfiguration;
    //EcoResProductMasterConfiguration    ecoResProductMasterConfiguration;
    EcoResProduct                       ecoResProduct = InventTable::find(_itemId).Product();

    ttsbegin;

    inventDimLoc.configId         = _inventDim.configId;
    inventDimLoc.InventSizeId     = _inventDim.InventSizeId;
    inventDimLoc.InventColorId    = _inventDim.InventColorId;
    inventDimLoc.InventStyleId    = _inventDim.InventStyleId;
    inventDimLoc                  = InventDim::findOrCreate(inventDimLoc);

    if (!InventDimCombination::find(_itemId, inventDimLoc.inventDimId))
    {


        this.releaseVariant(ecoResProduct, inventDimLoc);    // Release the variant
    }

    ttscommit;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_ecoResProduct">_ecoResProduct</param>
/// <param name = "_inventDim">_inventDim</param>
public void releaseVariant(EcoResProduct                  _ecoResProduct,
                           InventDim                      _inventDim)
{
    EcoResDistinctProductVariant        productVariant;
    EcoResProductReleaseManagerBase     releaseManager;
    container                           productVariantContainer;

    productVariantContainer = EcoResProductVariantDimValue::getDimensionValuesContainerByInventDim(_inventDim);

    productVariant = EcoResProductVariantManager::findDistinctProductVariant(_ecoResProduct.RecId, productVariantContainer);

    // Create product variant only if it is not created
    if (!productVariant)
    {
        productVariant.DisplayProductNumber = EcoResProductNumberBuilderVariant::buildFromProductNumberAndDimensions(
                                                    _ecoResProduct.productNumber(),
                                                    productVariantContainer);

        // Create Product variant with Product and dimensions provided
        RefRecId ecoResDistinctProductVariantRecId  = EcoResProductVariantManager::createProductVariant(
            _ecoResProduct.RecId, _ecoResProduct.SearchName, productVariantContainer, productVariant.DisplayProductNumber);

        // Find newly created Product Variant
        productVariant = ecoResDistinctProductVariant::find(ecoResDistinctProductVariantRecId);
    }

    releaseManager = EcoResProductReleaseManagerBase::newFromProduct(productVariant);
    releaseManager.release();

}
